import random

LETTERS = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j']

def task_func(num_keys, num_values):
    # If no keys are requested, return an empty dict
    if num_keys <= 0:
        return {}

    # Create a list of keys randomly chosen from LETTERS.
    # Use random.sample to ensure the keys are unique.
    # We can't choose more keys than available in LETTERS.
    keys = random.sample(LETTERS, min(num_keys, len(LETTERS)))

    # Create a list of numbers from 1 to num_values if num_values > 0, otherwise an empty list.
    values = [i for i in range(1, num_values + 1)]

    # Build the dictionary
    result = {key: values[:] for key in keys}
    return result

